import React from 'react';
import logo from '../images/Logo.png'; 
import first from '../images/1.png';
import second from '../images/2.png';
import third from '../images/3.png';
import fourth from '../images/4.png';

class LeftSlidebar extends React.Component {
    render() {
        return (
            <div className="left-sidebar">
                <div className="left-sidebar-header">
                <img src={logo} alt="logo" className='logo' />
                <h3>Система учета<br /> посещаемости</h3>
                </div>
                <div className="content-bar">
                    <div className="content-bar-item">
                        <img src={first} alt="first" />
                        <h4>Создание мероприятия</h4>
                    </div>
                    <div className="content-bar-item">
                        <img src={second} alt="second" />
                        <h4>Список созданных мероприятий</h4>
                    </div>
                    <div className="content-bar-item">
                        <img src={third} alt="third" />
                        <h4>Профиль</h4>
                    </div>
                    <div className="content-bar-item">
                        <img src={fourth} alt="fourth" />
                        <h4>Выход</h4>
                    </div>
                </div>
            </div>
        );
    }
}

export default LeftSlidebar;
